// One item per storyboard page of each new request (reminders send no pages). The worker serves
// the pages against the episode_code job's board token (D-055). Replace the base URL on import.
const WORKER = 'REPLACE_WITH_WORKER_URL';
const rows = $input.all().filter((item) => item.json.kind === 'REQUEST' && item.json.board);
return rows.flatMap(({ json: row }) => {
  const board = typeof row.board === 'string' ? JSON.parse(row.board) : row.board;
  const shortId = String(row.video_id).slice(0, 8);
  return board.pages.map((page, i) => ({
    json: {
      url: `${WORKER}/boards/${row.video_id}/${row.version}/${board.job_id}/${page.split('/').pop()}?t=${board.token}`,
      caption: `Video ${shortId} v${row.version} · storyboard ${row.round}/4 · page ${i + 1}/${board.pages.length}`,
    },
  }));
});

// One message with buttons per row from storyboard_approvals_due(), after its pages. System text is
// English; the title is quoted Vietnamese video content. Notes come back as a reply to this message
// (WF-06 finds the request by the trailing ref). Callback data: sb:<A|R>:<32-hex token>.
const rows = $input.all().filter((item) => typeof item.json.token === 'string');
return rows.map(({ json: row }) => {
  const shortId = String(row.video_id).slice(0, 8);
  const header = row.kind === 'REMINDER'
    ? `[AI Video] Reminder: storyboard approval pending (round ${row.round} of 4)`
    : `[AI Video] Storyboard ready for approval (round ${row.round} of 4)`;
  const text = [
    header,
    `Video ${shortId} v${row.version}`,
    `Title: ${row.title ?? '?'}`,
    '',
    'Approve to render the preview. To ask for changes, reply to this message with your notes.',
    `Expires: ${new Date(row.expires_at).toISOString().replace('T', ' ').slice(0, 16)} UTC`,
    `ref:${row.token}`,
  ].join('\n');
  return { json: { text, approve: `sb:A:${row.token}`, reject: `sb:R:${row.token}` } };
});
